const G1_COMPRESSED_SIZE: usize = 48;
const G2_COMPRESSED_SIZE: usize = 96;

fn deserialize_arkworks_03_vk(bytes: &[u8]) -> Result<VerifyingKey<Bls12_381>, FastCryptoError> {
    if bytes.len() < 4 * G2_COMPRESSED_SIZE - G1_COMPRESSED_SIZE + 8 {
        return Err(FastCryptoError::InvalidInput);
    }

    let gamma_len_offset = G1_COMPRESSED_SIZE + 3 * G2_COMPRESSED_SIZE;
    let gamma_len = u64::from_le_bytes(
        bytes[gamma_len_offset..gamma_len_offset + 8]
            .try_into()
            .map_err(|_| FastCryptoError::InvalidInput)?,
    ) as usize;
    let gamma_start = gamma_len_offset + 8;
    if bytes.len() != gamma_start + gamma_len * G1_COMPRESSED_SIZE {
        return Err(FastCryptoError::InvalidInput);
    }

    let mut gamma_abc_g1 = Vec::with_capacity(gamma_len);
    for g1_bytes in bytes[gamma_start..].chunks(G1_COMPRESSED_SIZE) {
        gamma_abc_g1.push(deserialize_g1_arkworks_03_compressed(g1_bytes)?);
    }

    Ok(VerifyingKey {
        alpha_g1: deserialize_g1_arkworks_03_compressed(&bytes[0..G1_COMPRESSED_SIZE])?,
        beta_g2: deserialize_g2_arkworks_03_compressed(
            &bytes[G1_COMPRESSED_SIZE..G1_COMPRESSED_SIZE + G2_COMPRESSED_SIZE],
        )?,
        gamma_g2: deserialize_g2_arkworks_03_compressed(
            &bytes[G1_COMPRESSED_SIZE + G2_COMPRESSED_SIZE
                ..G1_COMPRESSED_SIZE + 2 * G2_COMPRESSED_SIZE],
        )?,
        delta_g2: deserialize_g2_arkworks_03_compressed(
            &bytes[G1_COMPRESSED_SIZE + 2 * G2_COMPRESSED_SIZE
                ..G1_COMPRESSED_SIZE + 3 * G2_COMPRESSED_SIZE],
        )?,
        gamma_abc_g1,
    })
}

fn deserialize_arkworks_03_proof(bytes: &[u8]) -> Result<Proof<Bls12_381>, FastCryptoError> {
    if bytes.len() != 2 * G1_COMPRESSED_SIZE + G2_COMPRESSED_SIZE {
        return Err(FastCryptoError::InvalidInput);
    }

    Ok(Proof {
        a: deserialize_g1_arkworks_03_compressed(&bytes[..G1_COMPRESSED_SIZE])?,
        b: deserialize_g2_arkworks_03_compressed(
            &bytes[G1_COMPRESSED_SIZE..G1_COMPRESSED_SIZE + G2_COMPRESSED_SIZE],
        )?,
        c: deserialize_g1_arkworks_03_compressed(&bytes[G1_COMPRESSED_SIZE + G2_COMPRESSED_SIZE..])?,
    })
}

/// Deserialize bytes as an Arkwork representation of a verifying key, and return a vector of the four components of a prepared verified key (see more at [`crate::verifier::PreparedVerifyingKey`]).
pub fn prepare_pvk_bytes(vk_bytes: &[u8]) -> Result<Vec<Vec<u8>>, FastCryptoError> {
    let vk = VerifyingKey::<Bls12_381>::deserialize_compressed_unchecked(vk_bytes)
        .map_err(|_| FastCryptoError::InvalidInput)
        .or_else(|_| deserialize_arkworks_03_vk(vk_bytes))?;

    process_vk_special(&vk).as_serialized()
}

/// Verify Groth16 proof using the serialized form of the four components in a prepared verifying key
/// (see more at [`crate::verifier::PreparedVerifyingKey`]), serialized proof public input and serialized proof points.
pub fn verify_groth16_in_bytes(
    vk_gamma_abc_g1_bytes: &[u8],
    alpha_g1_beta_g2_bytes: &[u8],
    gamma_g2_neg_pc_bytes: &[u8],
    delta_g2_neg_pc_bytes: &[u8],
    proof_public_inputs_as_bytes: &[u8],
    proof_points_as_bytes: &[u8],
) -> Result<bool, FastCryptoError> {
    let x = BlsFr::deserialize_compressed_unchecked(proof_public_inputs_as_bytes)
        .map_err(|_| FastCryptoError::InvalidInput)?;

    let proof = Proof::<Bls12_381>::deserialize_compressed_unchecked(proof_points_as_bytes)
        .map_err(|_| FastCryptoError::InvalidInput)
        .or_else(|_| deserialize_arkworks_03_proof(proof_points_as_bytes))?;

