        vk_gamma_abc_g1_bytes,
        alpha_g1_beta_g2_bytes,
        gamma_g2_neg_pc_bytes,
        delta_g2_neg_pc_bytes,
    )?;

    verify_with_processed_vk(&blst_pvk, &[x], &proof)
        .map_err(|_| FastCryptoError::GeneralOpaqueError)
}

